fn solve(x: i32) -> i32 {
    // Convert x to string to extract digit and length
    let s = x.to_string();
    let d = s.chars().next().unwrap().to_digit(10).unwrap() as i32;
    let k = s.len() as i32;

    // Calculate presses contributed by all boring numbers with digits less than d:
    // For each digit less than d, it has 4 numbers (lengths 1 to 4),
    // each requiring length button presses.
    // Total presses for each digit = 1 + 2 + 3 + 4 = 10
    let presses_before = (d - 1) * 10;

    // Calculate presses contributed by the boring numbers with the digit d
    // but lengths less than k: sum of 1..(k-1)
    let presses_same_digit_before = (k * (k + 1)) / 2;

    presses_before + presses_same_digit_before
}